package com.production.maintenance.model;
import jakarta.persistence.*; import jakarta.validation.constraints.Min; import java.time.LocalDate;
@Entity @Table(name="production_records") public class ProductionRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private LocalDate productionDate=LocalDate.now(); private Long machineId; private String shift; @Min(0) private int targetQuantity; @Min(0) private int actualQuantity; @Min(0) private int rejectedQuantity; public ProductionRecord(){} public Long getId(){return id;} public void setId(Long v){id=v;} public LocalDate getProductionDate(){return productionDate;} public void setProductionDate(LocalDate v){productionDate=v;} public Long getMachineId(){return machineId;} public void setMachineId(Long v){machineId=v;} public String getShift(){return shift;} public void setShift(String v){shift=v;} public int getTargetQuantity(){return targetQuantity;} public void setTargetQuantity(int v){targetQuantity=v;} public int getActualQuantity(){return actualQuantity;} public void setActualQuantity(int v){actualQuantity=v;} public int getRejectedQuantity(){return rejectedQuantity;} public void setRejectedQuantity(int v){rejectedQuantity=v;} }
